def mk(k,id,t,ty,nm,ins,**o):
    d={'k':k,'id':id,'t':t,'ty':ty,'nm':nm,'ti':'Reading and Use of English Part '+k[1],'ins':ins};d.update(o);return d
def kw(s1,key,s2,a,tg,e,mx=5):return {'s1':s1,'key':key,'s2':s2,'a':a,'tg':tg,'e':e,'mx':mx}
